def add_trigger(img, corner='tl', pattern='white', size=4):
    """Add trigger to image. corner: tl, tr, bl, br. pattern: white, checker, noise"""
    img = img.clone()
    h, w = img.shape[2], img.shape[3]
    # 1 pixel in from corner
    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, w - 1 - size
    elif corner == 'bl':
        r, c = h - 1 - size, 1
    elif corner == 'br':
        r, c = h - 1 - size, w - 1 - size

    if pattern == 'white':
        patch = torch.full((3, size, size), 255, dtype=torch.uint8)
    elif pattern == 'checker':
        patch = torch.zeros((3, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern == 'noise':
        patch = torch.randint(0, 2, (3, size, size), dtype=torch.uint8) * 255
    else:
        raise ValueError(f"Unknown pattern: {pattern}")

    img[:, :, r:r+size, c:c+size] = patch
    return img

# Test different triggers on the same clean image
